def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    frame = max(counts, key=counts.get)

    # The frame-colored grid lines divide the picture into cells.
    rows = [r for r in range(h) if sum(v == frame for v in grid[r]) >= w - 2]
    cols = [c for c in range(w) if sum(grid[r][c] == frame for r in range(h)) >= h - 2]

    # The most common non-frame color is the empty-cell color.
    bg = max((v for v in counts if v != frame), key=lambda v: counts[v])

    out = []
    for r1, r2 in zip(rows, rows[1:]):
        line = []
        for c1, c2 in zip(cols, cols[1:]):
            corners = [grid[r1][c1], grid[r1][c2],
                       grid[r2][c1], grid[r2][c2]]
            if corners[0] != frame and all(v == corners[0] for v in corners):
                line.append(corners[0])
            else:
                line.append(bg)
        out.append(line)
    return out
